package pe.ganadoconecta.modulos.reproduccion.aplicacion;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;import pe.ganadoconecta.modulos.ganado.aplicacion.UnidadDeTrabajo;import pe.ganadoconecta.modulos.identidad.aplicacion.*;import pe.ganadoconecta.modulos.reproduccion.dominio.*;
public final class RegistrarParto{private final UnidadDeTrabajo u;private final AutorizarAccesoGanaderiaTransaccional auth;private final RepositorioPartos repo;private final Clock reloj;public RegistrarParto(UnidadDeTrabajo u,AutorizarAccesoGanaderiaTransaccional a,RepositorioPartos r,Clock c){this.u=u;auth=a;repo=r;reloj=c;}public ResultadoRegistroParto ejecutar(SolicitudParto s,UUID actor,UUID sesion){if(s==null||s.operationId()==null||s.operationId().version()!=4)throw new DatoReproductivoInvalidoException("operationId");if(s.schemaVersion()!=1)throw new DatoReproductivoInvalidoException("schemaVersion");Instant ahora=reloj.instant().truncatedTo(ChronoUnit.MICROS);var p=new Parto(s.partoId(),s.ganaderiaId(),s.madreId(),s.padreId(),s.fecha(),s.resultado(),s.observaciones(),s.criaIds(),actor,ahora);p.validarNoFuturo(ahora.atZone(ZoneId.of("America/Lima")).toLocalDate());byte[]h=huella(p,s.operationId());return u.ejecutar(()->{auth.autorizar(actor,sesion,s.ganaderiaId(),PermisoGanaderia.ESCRIBIR,ahora);return repo.registrar(p,s.operationId(),h,s.schemaVersion());});}private static byte[]huella(Parto p,UUID op){try{return MessageDigest.getInstance("SHA-256").digest(String.join("\u001f",op.toString(),p.id().toString(),p.ganaderiaId().toString(),p.madreId().toString(),Objects.toString(p.padreId(),""),p.fecha().toString(),p.resultado().name(),Objects.toString(p.observaciones(),""),p.criaIds().stream().map(UUID::toString).sorted().toList().toString(),p.creadoPor().toString()).getBytes(StandardCharsets.UTF_8));}catch(NoSuchAlgorithmException x){throw new IllegalStateException(x);}}}
